import org.junit.jupiter.api.Test;
import org.mockito.Mockito;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

class UserServiceTest {
  @Test
  void testGetUserName() {
    // Arrange: Criar mock do repositório
    UserRepository repo = Mockito.mock(UserRepository.class);
    when(repo.findNameById(1L)).thenReturn("João");
    UserService service = new UserService(repo);

    // Act: Chamar método do serviço
    String name = service.getUserName(1L);

    // Assert: Verificar resultado e interação
    assertEquals("João", name);
    verify(repo).findNameById(1L); // Verifica se o método foi chamado
  }
}
interface UserRepository {
  String findNameById(Long id);
}
class UserService {
  private UserRepository repo;
  UserService(UserRepository repo) { this.repo = repo; }
  String getUserName(Long id) { return repo.findNameById(id); }
}

