import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import static org.junit.jupiter.api.Assertions.assertEquals;

class CalcTest {
  @ParameterizedTest
  @CsvSource({"2, 2, 4", "3, 3, 6", "0, 5, 5"})
  void testSoma(int a, int b, int expected) {
    Calc calc = new Calc();
    assertEquals(expected, calc.soma(a, b));
  }
}

import static org.assertj.core.api.Assertions.*;

@Test
void deveCalcularTotalDoPedido() {
    Pedido pedido = new Pedido(List.of(item("livro", "50.00"), item("caneta", "5.00")));

    assertThat(pedido.total()).isEqualByComparingTo("55.00");
    assertThat(pedido.itens()).hasSize(2)
                              .extracting(Item::nome)
                              .containsExactly("livro", "caneta");
}

@Test
void deveRejeitarQuantidadeNegativa() {
    assertThatThrownBy(() -> new Item("livro", -1))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessageContaining("quantidade");
}

